def select_questions(category: str, count: int, rng) -> list[dict]:
    pool = [q for q in QUESTIONS if category == "all" or q[0] == category]
    return [
        {
            "id": QUESTIONS.index(q),
            "category": q[0],
            "zh": q[1],
            "en": q[2],
            "optionsZh": list(q[3]),
            "optionsEn": list(q[4]),
        }
        for q in rng.sample(pool, count)
    ]
